18	import java.util.Map;
19	import java.util.Objects;
20	
21	/**
22	 * Maps Owner &amp; OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public abstract class OwnerMapper {
26	
27	    /**
28	     * A create is flagged with {@code bulkSignupWarning=true} once more than this many owners have
29	     * already been created on the same registration date.
30	     */
31	    private static final int BULK_SIGNUP_THRESHOLD = 80;
32	
33	    @Autowired
34	    protected ClinicService clinicService;
35	
36	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
37	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
38	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
39	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
40	    @Mapping(target = "locality", expression = "java(locality(owner))")
41	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
43	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
44	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
45	    public abstract OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
49	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
50	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
51	     * the registration date (against which the age is measured) is absent.
52	     */
53	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
54	        LocalDate birthDate = owner.getBirthDate();
55	        LocalDate registrationDate = owner.getRegistrationDate();
56	        if (birthDate == null || registrationDate == null) {
57	            return null;
58	        }
59	        int age = Period.between(birthDate, registrationDate).getYears();
60	        if (age < 18) {
61	            return OwnerDto.AgeBandEnum.MINOR;
62	        }
63	        if (age < 65) {
64	            return OwnerDto.AgeBandEnum.ADULT;
65	        }
66	        return OwnerDto.AgeBandEnum.SENIOR;
67	    }
68	
69	    /**
70	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key:
71	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A {@code null}
72	     * email or householdId contributes an empty segment.
73	     */
74	    protected String identityKey(Owner owner) {
75	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
76	        String email = owner.getEmail() == null ? "" : owner.getEmail();
77	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
78	        return telephone + "|" + email + "|" + householdId;
79	    }
80	
81	    /**
82	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
83	     * present, otherwise {@code PHONE}.
84	     */
85	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
87	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
88	    }
89	
90	    /**
91	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
92	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
93	     */
94	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
95	        "NSW", new int[] {2000, 2099},
96	        "VIC", new int[] {3000, 3099},
97	        "QLD", new int[] {4000, 4099});
98	
99	    /**
100	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
101	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
102	     * moves in lockstep with the identity assigned on create. When no customer code has been
103	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
104	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
105	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
